import React, { useState } from 'react';
import { useWallet } from '../hooks/useData';
import api from '../services/api';

const Wallet: React.FC = () => {
  const { wallet, loading, error } = useWallet();
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [withdrawLoading, setWithdrawLoading] = useState(false);

  const handleWithdraw = async () => {
    if (!withdrawAmount) return;

    setWithdrawLoading(true);
    try {
      await api.post('/wallet/withdraw', {
        amount: parseFloat(withdrawAmount),
        bankAccount: '1234567890',
        bankIFSC: 'SBIN0001234',
        accountHolder: 'Account Holder Name',
      });
      alert('Withdrawal request submitted!');
      setWithdrawAmount('');
    } catch (err: any) {
      alert(err.response?.data?.message || 'Withdrawal failed');
    } finally {
      setWithdrawLoading(false);
    }
  };

  if (loading) return <div className="text-center py-12">Loading wallet...</div>;
  if (error) return <div className="text-red-500 text-center py-12">{error}</div>;

  return (
    <div className="space-y-6">
      <h1 className="text-3xl font-bold text-gray-800">My Wallet</h1>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="card bg-gradient-to-br from-blue-500 to-blue-600 text-white">
          <p className="text-blue-100">Total Balance</p>
          <p className="text-4xl font-bold mt-2">₹{wallet?.balance || 0}</p>
        </div>

        <div className="card bg-gradient-to-br from-green-500 to-green-600 text-white">
          <p className="text-green-100">Commission Earned</p>
          <p className="text-4xl font-bold mt-2">₹{wallet?.commissionEarned || 0}</p>
        </div>

        <div className="card bg-gradient-to-br from-purple-500 to-purple-600 text-white">
          <p className="text-purple-100">Total Withdrawn</p>
          <p className="text-4xl font-bold mt-2">₹{wallet?.totalWithdrawn || 0}</p>
        </div>
      </div>

      <div className="card">
        <h2 className="text-xl font-bold mb-4">Request Withdrawal</h2>
        <div className="space-y-4">
          <input
            type="number"
            placeholder="Amount (minimum ₹500)"
            className="input-field"
            value={withdrawAmount}
            onChange={(e) => setWithdrawAmount(e.target.value)}
            min="500"
          />
          <button
            onClick={handleWithdraw}
            className="btn-primary"
            disabled={withdrawLoading || !withdrawAmount}
          >
            {withdrawLoading ? 'Processing...' : 'Request Withdrawal'}
          </button>
        </div>
      </div>

      <div className="card">
        <h2 className="text-xl font-bold mb-4">Recent Transactions</h2>
        <div className="space-y-3">
          {wallet?.transactions?.length ? (
            wallet.transactions.map((tx: any, idx: number) => (
              <div key={idx} className="flex justify-between items-center pb-3 border-b">
                <div>
                  <p className="font-semibold">{tx.type}</p>
                  <p className="text-gray-600 text-sm">{new Date(tx.createdAt).toLocaleDateString()}</p>
                </div>
                <p className={`font-bold ${tx.amount > 0 ? 'text-green-600' : 'text-red-600'}`}>
                  {tx.amount > 0 ? '+' : '-'}₹{Math.abs(tx.amount)}
                </p>
              </div>
            ))
          ) : (
            <p className="text-gray-600">No transactions yet</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default Wallet;
